#include <stack>
#include <iostream>

void dangerous_pop(std::stack<int>& s) {
    // DANGER: Precondition violation if s is empty
    s.pop(); 
    // Calling top() here would also be UB
}

int main() {
    std::stack<int> s;
    s.push(10);

    // Correct usage: Check empty() before operation
    if (!s.empty()) {
        std::cout << s.top() << std::endl;
        s.pop();
    }

    // dangerous_pop(s); // Calling this results in UB
    return 0;
}
